let doc=load("page2").report.chunk.content;
doc=doc.replace("Planning priority: high","Planning priority: low").replace("Requirements clarification: open","Requirements clarification: complete").replace("Required behavior when multiple notes match the same exact ID remains unanswered.","A unique match shows exactly one matched path. Missing matches are explicit. Multiple matches remain explicitly ambiguous; never choose by recency. Preserve all sources.").replace("Multiple-match behavior must be clarified before this UR is complete.","For exactly one match, show exactly one matched path. Distinguish missing and ambiguous cases explicitly; never choose among multiple matches by recency. Preserve all sources.").replace("Existing local evidence notes in the confirmed project are the source of truth. Their specific paths and ownership have not been established; no alternative source is assumed.","The project's existing evidence-note conventions are the current source of truth. Respect existing local notes and preserve all sources.").replace("Open material question: What should happen when multiple existing local evidence notes match the same exact ID? No answer is assumed.","Multiple matches must remain explicitly ambiguous and must never be resolved by recency. Missing matches must be explicit too. The user has confirmed no other unknowns remain.").replace("Clarify the multiple-match behavior and review this incomplete planned UR. Keep requirements clarification open. No Run, approval, or delivery is requested.","Retain this clarified planned UR for review. Do not start a Run until a later deliberate handoff request. Gate approval remains open; this save approves nothing.");
store("doc",doc);
const q=s=>"'"+s.replace(/'/g,"'\\''")+"'";
const r=await tools.exec_command({cmd:"python3 -c "+q("import sys,base64,uuid,json\ns=sys.argv[1].encode('utf-8')\nprint(json.dumps({'bytes':len(s),'data':base64.b64encode(s).decode(),'ids':[str(uuid.uuid4()) for _ in range(4)]}))")+" "+q(doc)});store("enc",JSON.parse(r.output));text({bytes:load("enc").bytes,ids:load("enc").ids});
store("env",{...load("b"),planning:load("p"),target_id:load("contract").report.binding.target_id,schema_version:"1",assurance:"cooperative_local"});
